const upd = $json;
const cq = upd.callback_query;
const msg = cq ? cq.message : upd.message;
const from = cq ? cq.from : (upd.message ? upd.message.from : {});
const chat_id = msg && msg.chat ? msg.chat.id : (from ? from.id : null);
const telegram_id = String(from && from.id ? from.id : '');
const nombre_usuario = [from && from.first_name, from && from.last_name].filter(Boolean).join(' ');
let raw = cq ? String(cq.data || '') : String((upd.message && upd.message.text) || '').trim();
let action = 'UNKNOWN';
let param = '';
if (cq) {
  if (raw === 'START') action = 'START';
  else if (raw === 'MENU' || raw === 'CATS') action = 'CATS';
  else if (raw.indexOf('CAT:') === 0) { action = 'PRODUCTS'; param = raw.slice(4); }
  else if (raw.indexOf('ADD:') === 0) { action = 'ADD'; param = raw.slice(4); }
  else if (raw.indexOf('QTY+:') === 0) { action = 'QTYUP'; param = raw.slice(5); }
  else if (raw.indexOf('QTY-:') === 0) { action = 'QTYDOWN'; param = raw.slice(5); }
  else if (raw === 'CART') action = 'CART';
  else if (raw === 'CONFIRM') action = 'CONFIRM';
  else if (raw === 'CLEAR') action = 'CLEAR';
  else if (raw === 'STATUS') action = 'STATUS';
  else if (raw === 'HISTORY') action = 'HISTORY';
} else {
  const t = raw.toLowerCase();
  if (t === '/start' || t === 'start' || t === 'hola' || t === 'inicio') action = 'START';
  else if (/^p\d+$/i.test(t)) { action = 'ADD'; param = t.toUpperCase(); }
  else if (/^-p\d+$/i.test(t)) { action = 'QTYDOWN'; param = t.slice(1).toUpperCase(); }
  else if (t.indexOf('/add ') === 0) { action = 'ADD'; param = t.replace('/add ', '').toUpperCase(); }
  else if (t.indexOf('menu') !== -1 || t.indexOf('menú') !== -1) action = 'CATS';
  else if (t.indexOf('carrito') !== -1) action = 'CART';
  else if (t.indexOf('confirmar') !== -1) action = 'CONFIRM';
  else if (t.indexOf('vaciar') !== -1) action = 'CLEAR';
  else if (t.indexOf('estado') !== -1 || t.indexOf('pedido') !== -1) action = 'STATUS';
  else if (t.indexOf('historial') !== -1) action = 'HISTORY';
}
return [{ json: { chat_id, telegram_id, nombre_usuario, action, param, raw, now: new Date().toISOString() } }];

const base = $('Normalizar entrada').first().json;
const cat = String(base.param || '');
const rows = $input.all().map(i => i.json).filter(r => r && r.id_producto);
const av = rows.filter(r => String(r.categoria).toLowerCase() === cat.toLowerCase() && Number(r.stock || 0) > 0);
let text;
if (!av.length) {
  text = 'No hay productos disponibles en ' + cat + '.';
} else {
  text = '📋 *' + cat.toUpperCase() + '*\n━━━━━━━━━━━━━━\n\n';
  for (const r of av) {
    text += '🍽 *' + r.id_producto + '* — ' + r.nombre + '\n';
    text += '   💲 $' + Number(r.precio).toLocaleString('es-CO') + '\n\n';
  }
  text += '✏️ Escribe el código (ej: `' + av[0].id_producto + '`) para agregarlo al carrito.';
}
return [{ json: { chat_id: base.chat_id, text } }];

const base = $('Normalizar entrada').first().json;
const menu = $('Leer MENU agregar').all().map(i => i.json).filter(r => r && r.id_producto);
const sess = $('Consultar SESSIONS agregar').all().map(i => i.json).filter(r => r && r.telegram_id);
const row = sess.find(r => String(r.telegram_id) === base.telegram_id);
let cart = [];
try { cart = row && row.carrito_temporal ? JSON.parse(row.carrito_temporal) : []; } catch (e) { cart = []; }
const pid = String(base.param || '').toUpperCase();
const prod = menu.find(x => String(x.id_producto).toUpperCase() === pid);
let msg;
if (!prod) {
  msg = 'No encontré el producto ' + pid + '. Escribe un código válido (ej: P001).';
} else {
  const idx = cart.findIndex(x => String(x.id_producto).toUpperCase() === pid);
  let delta = base.action === 'QTYDOWN' ? -1 : 1;
  if (idx >= 0) {
    cart[idx].cantidad = Number(cart[idx].cantidad) + delta;
    if (cart[idx].cantidad <= 0) cart.splice(idx, 1);
  } else if (delta > 0) {
    cart.push({ id_producto: prod.id_producto, nombre: prod.nombre, cantidad: 1, precio: Number(prod.precio) });
  }
  msg = '✅ ' + prod.nombre + ' actualizado en tu carrito.';
}
return [{ json: { telegram_id: base.telegram_id, chat_id: base.chat_id, pantalla_actual: 'carrito', carrito_temporal: JSON.stringify(cart), ultimo_cambio: new Date().toISOString(), _msg: msg } }];

const base = $('Normalizar entrada').first().json;
const sess = $input.all().map(i => i.json).filter(r => r && r.telegram_id);
const row = sess.find(r => String(r.telegram_id) === base.telegram_id);
let cart = [];
try { cart = row && row.carrito_temporal ? JSON.parse(row.carrito_temporal) : []; } catch (e) { cart = []; }
let text;
let total = 0;
if (cart.length) {
  text = '🛒 MI CARRITO\n\n';
  for (const x of cart) {
    const sub = Number(x.precio) * Number(x.cantidad);
    total += sub;
    text += x.nombre + ' x' + x.cantidad + ' = $' + sub.toLocaleString('es-CO') + '\n';
  }
  text += '\nTotal: $' + total.toLocaleString('es-CO');
} else {
  text = '🛒 Tu carrito está vacío. Escribe "menu" para ver productos.';
}
return [{ json: { chat_id: base.chat_id, text } }];

const base = $('Normalizar entrada').first().json;
const menu = $('Leer MENU confirmar').all().map(i => i.json).filter(r => r && r.id_producto);
const sess = $('Consultar SESSIONS confirmar').all().map(i => i.json).filter(r => r && r.telegram_id);
const row = sess.find(r => String(r.telegram_id) === base.telegram_id);
let cart = [];
try { cart = row && row.carrito_temporal ? JSON.parse(row.carrito_temporal) : []; } catch (e) { cart = []; }
if (!cart.length) {
  return [{ json: { ok: false, chat_id: base.chat_id, motivo: '🛒 Tu carrito está vacío. Agrega productos antes de confirmar.' } }];
}
const faltantes = [];
let total = 0;
const updates = [];
for (const it of cart) {
  const m = menu.find(x => String(x.id_producto) === String(it.id_producto));
  const stock = m ? Number(m.stock || 0) : 0;
  if (Number(it.cantidad) > stock) {
    const deficit = Number(it.cantidad) - stock;
const vecesTexto = deficit === 1 ? '1 vez' : deficit + ' veces';
faltantes.push('*' + it.nombre + '* — pediste ' + it.cantidad + ', solo hay ' + stock + '.\n   👉 Escribe `-' + it.id_producto + '` (' + vecesTexto + ') y vuelve a confirmar.');
  } else {
    total += Number(it.precio) * Number(it.cantidad);
    updates.push({ id_producto: it.id_producto, stock: stock - Number(it.cantidad) });
  }
}
if (faltantes.length) {
  return [{ json: { ok: false, chat_id: base.chat_id, motivo: '⚠️ *Sin stock suficiente:*\n\n' + faltantes.join('\n\n') + '\n\nCuando ajustes, toca *Confirmar* de nuevo.' } }];
}
const d = new Date();
const p = n => String(n).padStart(2, '0');
const fecha = p(d.getDate()) + '/' + p(d.getMonth() + 1) + '/' + d.getFullYear();
const hora = p(d.getHours()) + ':' + p(d.getMinutes());
const id_pedido = 'ORD-' + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + '-' + p(d.getHours()) + p(d.getMinutes()) + p(d.getSeconds());
return [{ json: { ok: true, chat_id: base.chat_id, telegram_id: base.telegram_id, nombre_usuario: base.nombre_usuario, id_pedido, total_pago: total, detalles_pedido: JSON.stringify(cart), estado: 'Recibido', fecha, hora, updates } }];

